        "expense_cap",
        "hospitality_cap",
        "ratchet",
        "walkout_pot",
        "bonuses",
        "global",
      ],
    },
    description: { type: Type.STRING },
    evidence_quote: { type: Type.STRING, nullable: true },
  },
  required: ["flag_class", "field_affected", "description"],
};

export const geminiResponseSchema: Schema = {
